function term(l){return l==="5e"?"Unidad":"Secuencia"} function track(l){return l==="5e"?"Descubrir":l==="4e"?"Comunicar":"Actuar"} function bc(l){return l==="5e"?"b5":l==="4e"?"b4":"b3"}
function titleFor(c){return c.level==="4e"?(T4[c.seq]||"Secuencia "+c.seq):c.level==="5e"?(T5[c.seq]||"Unidad "+c.seq):(S3E[String(c.seq)]?.title||"Secuencia "+c.seq)}
function legacy_rc4_maxS_20(c){return c.level==="4e"?(C4[c.seq]||6):c.level==="3e"?(S3E[String(c.seq)]?.count||6):6}
function isEval(d){let s=(d.category+" "+d.name).toLowerCase();return /évaluation|evaluation|mini.?test|mini.?éval|qcm|corrig|bar[eè]me|matrice d.?évaluation/.test(s)}
function isFinalDoc(d){let s=(d.category+" "+d.name).toLowerCase();return /proyecto.?final|projet.?final|tâche.?final|tarea.?final/.test(s)}
function unique(a){let x=new Set();return a.filter(d=>!x.has(d.url)&&(x.add(d.url),true))}
function legacy_rc4_courseDocs_24(c){return unique(DOCS.filter(d=>{
 if(d.level!==c.level||d.seq!==c.seq||isEval(d))return false;
 if(d.is_course_resource===false)return false;
 if(isFinalDoc(d)&&c.session!==maxS(c))return false;
 if(d.session!=null&&d.session!==c.session)return false;
 return true;
}))}
function legacy_rc4_evalDocs_31(c){return unique(DOCS.filter(d=>d.level===c.level&&d.seq===c.seq&&isEval(d)&&(d.session===c.session||d.session==null)))}
function legacy_rc4_sessionData_32(c){if(c.level==="3e")return S3E[String(c.seq)]?.[String(c.session)]||null;if(c.level==="4e"){let tr=TRACE4[String(c.seq)]?.[String(c.session)]||{},pl=PLAN4[String(c.seq)]?.[String(c.session)]||{};return {...tr,...pl,title:tr.title||pl.title||titleFor(c)}}return null}
function go(p){state.previous=state.page;state.page=p;save();render()}
function legacy_rc4_shell_34(){return `<div class="shell"><aside class="side"><div class="brand"><div><b>CAP-</b><strong>ESPAÑOL</strong></div><small><span class="agenda-label">AGENDA ENSEIGNANT</span><br><span class="agenda-year">${st.year||'2026-2027'}</span></small></div><div class="profile"><div class="avatar">SH</div><div class="profile-copy"><b class="teacher-name">Sr Hassini</b><div class="school-sep"></div><small class="school-info">Collège Guy Môquet<br>Gennevilliers (92) • Salle 104</small></div></div><nav>${NAV.map(n=>`<button data-page="${n[0]}" class="${state.page===n[0]?"on":""}"><b class="nav-svg">${uiIcon(n[0])}</b><span>${n[2]}</span></button>`).join("")}</nav><div class="side-mascot"><img class="mascot-reference-approved" src="mascotte-sidebar-reference-validee.png" alt="Caricature Sr Hassini validée"></div><div class="sidefoot"><div>Planifier • Enseigner • Suivre • Renseigner</div></div></aside><main><header><div class="headrow"><button id="back">←</button><div><h1 id="ttl"></h1><div id="sub"></div></div></div><div>▣ ${state.settings.year} &nbsp; <b>Sr Hassini</b></div></header><section id="content"></section><footer>❝ Enseñar es dejar una huella en la vida de otra persona. ❞ <span>Sr Hassini</span></footer></main><div id="visualModal" class="visual-modal"><button id="closeVisual">×</button><img id="visualModalImg" alt="Visuel pédagogique"></div></div>`}
function head(a,b=""){$("#ttl").textContent=a;$("#sub").textContent=b}
function k(l,v,c,s){return `<div class="card kpi"><b class="${c}">${l}</b><div>${v}</div><small>${s}</small></div>`}
function legacy_rc4_today_37(){head("AUJOURD’HUI","Agenda enseignant CAP-Espagnol 2026-2027");return `<div class="grid kpis">${k("CLASSES",state.classes.length,"violet","classes / groupes")}${k("À REPRENDRE",Object.values(state.status).filter(x=>x==="review").length,"orange","séances / notions")}${k("PRONOTE",state.classes.filter(c=>!state.pronote[c.id+"-"+c.seq+"-"+c.session]).length,"green","à renseigner")}${k("RESSOURCES",DOCS.filter(d=>!isEval(d)).length,"blue","documents")}</div><div class="gap"></div><div class="card"><h3>ACCÈS RAPIDE AUX CLASSES</h3>${state.classes.map(c=>`<div class="course"><span class="badge ${bc(c.level)}">${c.id}</span><div><h4>${track(c.level)} — ${term(c.level)} ${c.seq} — Séance ${c.session}</h4><p>${sessionData(c)?.title||titleFor(c)}</p></div><span>📁 ${courseDocs(c).length}</span><button class="open" data-open="${c.id}">Ouvrir →</button></div>`).join("")}</div>`}
function vocabHTML(v){return (v||[]).map(x=>`<div class="vline"><span class="v-es">${x.es||x}</span>${x.fr?`<span class="v-fr"> = ${x.fr}</span>`:""}</div>`).join("")}
function legacy_rc4_grammarHTML_39(g){if(!g)return "";return `<div class="grammar-point">${g.point||"GRAMÁTICA"}</div>${(g.examples||[]).map(x=>`<div class="grammar-ex">${x}</div>`).join("")}`}
function legacy_rc4_traceBlock_40(d,adapted=false){let x=adapted?d?.adapted:d;if(!x)return "";return `<div class="trace-sheet ${adapted?"adapted":""}"><h4>${adapted?"📗 VERSION ADAPTÉE":"📝 MI HUELLA ESCRITA"}</h4><div class="trace-section"><b class="vocab-head">🟢 VOCABULARIO</b>${vocabHTML(x.vocab)}</div><div class="trace-section"><b class="grammar-head">🔴 GRAMÁTICA</b>${grammarHTML(x.grammar)}</div><div class="trace-section"><b class="remember-head">🔵 LO QUE RECUERDO</b>${(x.trace||[]).map(z=>`<div class="trace-text">${z}</div>`).join("")}</div><div class="trace-section"><b>🏠 TAREA</b><div class="trace-text">${x.homework||"—"}</div></div></div>`}
function legacy_rc4_pronoteHTML_41(c,d){if(!d)return `<p class="muted">Aucun contenu structuré disponible.</p>`;return `<div class="pnpreview"><p><b>TITRE</b><br>${term(c.level)} ${c.seq} — Séance ${c.session} — ${d.title}</p><p><b>OBJECTIFS</b><br>${(d.objectives||[]).map(x=>"• "+x).join("<br>")}</p><p><b>ACTIVITÉS RÉALISÉES</b><br>${(d.activities||[]).map(x=>"• "+x).join("<br>")}</p><div class="pnbox"><b>VOCABULAIRE</b>${vocabHTML(d.vocab)}</div><div class="pnbox"><b>GRAMMAIRE / LANGUE</b>${grammarHTML(d.grammar)}</div><div class="pnbox"><b class="remember-head">TRACE ÉCRITE</b>${(d.trace||[]).map(x=>`<div class="trace-text">${x}</div>`).join("")}</div><p><b>TRAVAIL À FAIRE</b><br>${d.homework||"—"}</p></div>`}
function legacy_rc4_pronotePlain_42(c,d){if(!d)return "";let vv=(d.vocab||[]).map(x=>x.es+(x.fr?" = "+x.fr:"")).join("\n");return `TITRE\n${term(c.level)} ${c.seq} – Séance ${c.session} – ${d.title}\n\nOBJECTIFS\n${(d.objectives||[]).map(x=>"• "+x).join("\n")}\n\nACTIVITÉS RÉALISÉES\n${(d.activities||[]).map(x=>"• "+x).join("\n")}\n\nVOCABULAIRE\n${vv}\n\nGRAMMAIRE / LANGUE\n${d.grammar?.point||""}\n${(d.grammar?.examples||[]).join("\n")}\n\nTRACE ÉCRITE\n${(d.trace||[]).join("\n")}\n\nTRAVAIL À FAIRE\n${d.homework||""}`;}
function legacy_rc4_lesson_43(){let c=state.classes.find(x=>x.id===state.class)||state.classes[0],d=sessionData(c),sp=courseDocs(c),ev=evalDocs(c),sv=VIS_SEQ[c.level]?.[String(c.seq)]||VIS_LEVEL[c.level];head("FICHE SÉANCE",`${c.level} — ${track(c.level)} • ${titleFor(c)}`);return `<div class="card lessonhead"><div class="lesson-id"><span class="badge ${bc(c.level)}">${c.id}</span><h2>${term(c.level)} ${c.seq} — Séance ${c.session}</h2><b>${d?.title||titleFor(c)}</b><div class="pills"><span>S${c.session}/${maxS(c)}</span><span>${sp.length} ressource(s)</span><span>${ev.length} évaluation(s)</span></div></div>${sv?`<button class="visual-open lesson-visual" data-visual="${encodeURI(sv)}"><img src="${encodeURI(sv)}" alt="${titleFor(c)}"></button>`:""}</div><div class="grid two"><div><div class="card"><h3>OBJECTIFS & ACTIVITÉS</h3><h4>Objectifs de la séance</h4><ul>${(d?.objectives||[]).map(x=>`<li>${x}</li>`).join("")||"<li>Contenu non indexé.</li>"}</ul><h4>Activités réalisées / prévues</h4><ul>${(d?.activities||[]).map(x=>`<li>${x}</li>`).join("")||"<li>Contenu non indexé.</li>"}</ul></div><div class="gap"></div><div class="card"><h3>SUPPORTS / DOCUMENTS RÉELS</h3>${d?.supports?.length?`<div class="support-list">${d.supports.map(x=>`<div>• ${x}</div>`).join("")}</div>`:""}<div class="resgrid">${sp.length?sp.map(r=>`<div class="res"><div><b>${r.category}</b><small>${r.name}</small></div><a href="${encodeURI(r.url)}" target="_blank">Ouvrir</a></div>`).join(""):"<p class='muted'>Aucun fichier physique rattaché.</p>"}</div></div><div class="gap"></div><div class="card trace" id="tracePrint"><div class="trace-toolbar"><h3>TRACE ÉCRITE ÉLÈVE & DEVOIRS</h3><button class="outline" id="printTrace">Imprimer / PDF cette trace</button></div>${traceBlock(d,false)}${c.level==="4e"?traceBlock(d,true):""}</div><div class="gap"></div><div class="card eval"><h3>ÉVALUATIONS ASSOCIÉES</h3><div class="resgrid">${ev.length?ev.map(r=>`<div class="res"><div><b>${r.category}</b><small>${r.name}</small></div><a href="${encodeURI(r.url)}" target="_blank">Ouvrir</a></div>`).join(""):"<span class='muted'>Aucune évaluation rattachée à cette séance.</span>"}</div></div></div><div><div class="card pronote"><h3>PRONOTE — À COPIER / COLLER</h3>${pronoteHTML(c,d)}<div class="actions"><button class="primary" id="copyPronote">Copier le cahier de textes</button><button class="outline" id="savePronote">Marquer comme renseigné</button></div></div><div class="gap"></div><div class="card"><h3>FIN DU COURS</h3><div class="status"><button class="done" data-st="done">✓ TERMINÉ</button><button class="cont" data-st="continue">↻ À POURSUIVRE</button><button class="review" data-st="review">⚠ À REPRENDRE</button></div></div></div></div><div class="navlesson"><button class="outline" id="prevLesson">← Séance précédente</button><button class="outline" id="nextLesson">Séance suivante →</button></div>`}
const MONTHS=["Septembre","Octobre","Novembre","Décembre","Janvier","Février","Mars","Avril","Mai","Juin","Juillet"];
function weekAgenda(){let days=["LUNDI","MARDI","MERCREDI","JEUDI"];return `<div class="notice"><b>EMPLOI DU TEMPS 2026-2027</b> — grille hebdomadaire de référence à partir du 7 septembre. Les 1er, 2 et 3 septembre sont des temps de rentrée / premier contact, hors progression. Aucun cours le vendredi. Les cartes ci-dessous correspondent uniquement aux séances pédagogiques à compter du 7 septembre. Elles ne s’appliquent pas aux 1er, 2 et 3 septembre.</div><div class="weekgrid fourdays">${days.map((day,i)=>`<div class="daycol"><h3>${day}</h3>${EDT.filter(e=>e.day===i).map(e=>{let isSpanish=e.type==="ESPAGNOL LV2",canOpen=isSpanish&&state.classes.some(c=>c.id===e.class),special=!isSpanish;return `<button class="event level-${e.level} ${special?"special":""} ${(canOpen||special)?"clickable":""}" ${canOpen?`data-open="${e.class}"`:special?`data-special="${e.type}" data-special-class="${e.class}"`:"disabled"}><b>${e.start} – ${e.end}${e.week?` • Semaine ${e.week}`:""}</b><strong>${e.class}</strong><span>${e.type}</span><small>Salle 104${canOpen?"":special?"":""}</small></button>`}).join("")}</div>`).join("")}</div><div class="friday-note"><b>VENDREDI</b><span>Aucun cours</span></div>`}

function legacy_rc4_specialSession_47(type,cls){state.previous=state.page;state.page="special";state.specialType=type;state.specialClass=cls;save();render()}
function legacy_rc4_specialPage_48(){let type=state.specialType||"TSO",cls=state.specialClass||"3G";head(type,`${cls} • Trame provisoire`);return `<div class="card special-template"><div class="special-head"><div><span class="badge b3">${cls}</span><h2>${type}</h2><p class="muted">Trame volontairement vide en attente de la progression dédiée.</p></div></div><div class="special-empty-grid"><div class="emptybox"><h3>OBJECTIFS</h3><p>Aucun contenu défini pour le moment.</p></div><div class="emptybox"><h3>DÉROULEMENT / ACTIVITÉS</h3><p>Aucun contenu défini pour le moment.</p></div><div class="emptybox"><h3>TRACE / NOTES</h3><p>Aucun contenu défini pour le moment.</p></div><div class="emptybox"><h3>PRONOTE</h3><p>Aucun contenu d’espagnol n’est généré pour ce créneau.</p></div></div></div>`}

function legacy_rc4_monthAgenda_50(){let y=agendaMonth<4?2026:2027,m=(agendaMonth+4)%12;let name=MONTHS[(m>=8?m-8:m+4)]||new Date(y,m,1).toLocaleString("fr-FR",{month:"long"});let first=new Date(y,m,1),days=new Date(y,m+1,0).getDate(),offset=(first.getDay()+6)%7;return `<div class="monthnav"><button id="monthPrev">←</button><h2>${name} ${y}</h2><button id="monthNext">→</button></div><div class="monthgrid">${["Lun","Mar","Mer","Jeu","Ven","Sam","Dim"].map(x=>`<b>${x}</b>`).join("")}${Array.from({length:offset},()=>"<div class='empty'></div>").join("")}${Array.from({length:days},(_,i)=>`<div class="datecell"><b>${i+1}</b></div>`).join("")}</div>`}
function legacy_rc4_agenda_51(){head("MON AGENDA",agendaView==="week"?"Emploi du temps provisoire":agendaView==="month"?"Vue mois":"Calendrier annuel 2026-2027");let body=agendaView==="week"?weekAgenda():agendaView==="month"?monthAgenda():`<div class="card"><h3>CALENDRIER ANNUEL 2026-2027</h3><p class="muted">Cliquez sur un mois pour ouvrir sa vue mensuelle.</p><div class="yeargrid">${MONTHS.map((x,i)=>`<button class="monthbox" data-month="${i}"><b>${x}</b><small>Ouvrir le mois →</small></button>`).join("")}</div></div>`;return `<div class="toolbar"><button data-av="week" class="${agendaView==="week"?"on":""}">Emploi du temps</button><button data-av="month" class="${agendaView==="month"?"on":""}">Vue mois</button><button data-av="year" class="${agendaView==="year"?"on":""}">Vue année</button></div>${body}`}
function legacy_rc4_progress_52(){head("PROGRESSIONS","5e vert • 4e orange • 3e bleu foncé");return ["5e","4e","3e"].map(l=>{let cls="prog-"+l.replace("e","");let seqs=Array.from({length:7},(_,s)=>s).filter(s=>l!=="4e"||s>0);return `<div class="card prog ${cls}"><div class="progress-head"><div><h3>${l} — ${track(l)}</h3><p class="muted">Progression annuelle et accès aux visuels de chaque ${term(l).toLowerCase()}.</p></div>${VIS_PROGRESS[l]?`<button class="visual-open progress-visual-btn" data-visual="${encodeURI(VIS_PROGRESS[l])}"><img src="${encodeURI(VIS_PROGRESS[l])}"><span>Agrandir la progression</span></button>`:""}</div><div class="seqgrid">${seqs.map(s=>{let title=l==="4e"?T4[s]:l==="5e"?T5[s]:S3E[String(s)]?.title||"";let count=l==="3e"?S3E[String(s)]?.count||6:l==="4e"?C4[s]||6:6;let sv=VIS_SEQ[l]?.[String(s)];return `<div class="seq"><div><b>${term(l)} ${s}</b><span>${title}</span><small>${count} séance(s)</small></div>${sv?`<button class="visual-open seq-visual" data-visual="${encodeURI(sv)}"><img src="${encodeURI(sv)}"><em>Voir le visuel</em></button>`:""}</div>`}).join("")}</div></div>`}).join("<div class='gap'></div>")}
function legacy_rc4_classesPage_53(){head("MES CLASSES","Charte CAP-Espagnol : 5e vert • 4e orange • 3e bleu foncé");return `<div class="classgrid">${state.classes.map(c=>{let lv=VIS_LEVEL[c.level],sv=VIS_SEQ[c.level]?.[String(c.seq)];return `<div class="card classcard level-${c.level}">${lv?`<button class="visual-open class-level-visual" data-visual="${encodeURI(lv)}"><img src="${encodeURI(lv)}"></button>`:""}<div class="class-content"><span class="badge ${bc(c.level)}">${c.id}</span><h2>${c.level} — ${track(c.level)}</h2><p>${term(c.level)} ${c.seq} • ${titleFor(c)}</p><p>Séance <b>${c.session}/${maxS(c)}</b></p>${sv?`<button class="visual-open current-seq-visual" data-visual="${encodeURI(sv)}"><img src="${encodeURI(sv)}"><span>Visuel de la ${term(c.level).toLowerCase()}</span></button>`:""}<button class="primary level-btn" data-open="${c.id}">Ouvrir la séance</button></div></div>`}).join("")}</div>`}
function legacy_rc4_pronotePage_54(){head("PRONOTE","Cahier de textes généré depuis la vraie fiche séance");return `<div class="card"><table><thead><tr><th>Classe</th><th>Séance</th><th>Statut</th><th></th></tr></thead><tbody>${state.classes.map(c=>{let k=c.id+"-"+c.seq+"-"+c.session;return `<tr><td><span class="badge ${bc(c.level)}">${c.id}</span></td><td>${term(c.level)} ${c.seq} • S${c.session} — ${sessionData(c)?.title||titleFor(c)}</td><td>${state.pronote[k]?"✓ Renseigné":"À renseigner"}</td><td><button class="open" data-open="${c.id}">Préparer</button></td></tr>`}).join("")}</tbody></table></div>`}
function legacy_rc4_resources_55(evalOnly=false){head(evalOnly?"ÉVALUATIONS":"RESSOURCES",evalOnly?"Standard • adaptée • professeur":"Bibliothèque réelle");let arr=DOCS.filter(d=>evalOnly?isEval(d):!isEval(d));let cats=["Tous",...new Set(arr.map(x=>x.category))];if(resFilter!=="Tous")arr=arr.filter(x=>x.category===resFilter);return `<div class="filters">${cats.map(x=>`<button data-filter="${x}" class="${resFilter===x?"on":""}">${x}</button>`).join("")}</div><div class="card"><table><thead><tr><th>Niveau</th><th>Type</th><th>Document</th><th>Rattachement</th><th></th></tr></thead><tbody>${arr.map(r=>`<tr><td><span class="badge ${bc(r.level)}">${r.level}</span></td><td>${r.category}</td><td>${r.name}</td><td>${r.seq!=null?term(r.level)+" "+r.seq:"Général"}${r.session?" • S"+r.session:""}</td><td><a class="open" href="${encodeURI(r.url)}" target="_blank">Ouvrir</a></td></tr>`).join("")}</tbody></table></div>`}
function legacy_rc4_notesPage_56(){head("SUIVI & NOTES","Outil sans données fictives");return `<div class="card"><h3>DONNÉES RÉELLES UNIQUEMENT</h3><p>Aucun nom d'élève ni aucune note fictive n'est préchargé. Ajoutez ou importez les listes réelles 2026-2027 lorsque vous les aurez.</p><button class="primary">Importer / ajouter des élèves</button></div>`}
function legacy_rc4_settings_57(){head("PARAMÈTRES / CONFIGURER MON ANNÉE","Configuration CAP-Espagnol");return `<div class="grid two"><div class="card"><h3>ANNÉE SCOLAIRE</h3><p>2026-2027 • Emploi du temps officiel</p><button class="outline" data-go="agenda">Voir l'emploi du temps</button></div><div class="card"><h3>CHARTE DES NIVEAUX</h3><p class="green">5e — Descubrir : vert</p><p class="orange">4e — Comunicar : orange</p><p class="darkblue">3e — Actuar : bleu foncé</p></div><div class="card"><h3>CHARTE DE LA TRACE</h3><p><span class="v-es">Vocabulaire espagnol</span> = traduction en noir</p><p><span class="grammar-point">Point grammatical</span> — exemples en noir</p><p><span class="culture-head">Trace écrite / culture</span></p></div><div class="card"><h3>SAUVEGARDE</h3><button class="primary" id="export">Exporter mes données</button></div></div>`}
function legacy_rc4_render_58(){$("#app").innerHTML=shell();let h=state.page==="home"?homePage():state.page==="today"?today():state.page==="lesson"?lesson():state.page==="progress"?progress():state.page==="agenda"?agenda():state.page==="classes"?classesPage():state.page==="pronote"?pronotePage():state.page==="resources"?resources(false):state.page==="eval"?resources(true):state.page==="notes"?notesPage():state.page==="special"?specialPage():settings();$("#content").innerHTML=h;bind()}
function legacy_rc4_bind_59(){document.querySelectorAll("[data-page]").forEach(b=>b.onclick=()=>go(b.dataset.page));document.querySelectorAll("[data-open]").forEach(b=>b.onclick=()=>{state.previous=state.page;state.class=b.dataset.open;state.page="lesson";save();render()});document.querySelectorAll("[data-special]").forEach(b=>b.onclick=()=>specialSession(b.dataset.special,b.dataset.specialClass));document.querySelectorAll("[data-filter]").forEach(b=>b.onclick=()=>{resFilter=b.dataset.filter;render()});document.querySelectorAll("[data-av]").forEach(b=>b.onclick=()=>{agendaView=b.dataset.av;render()});document.querySelectorAll("[data-month]").forEach(b=>b.onclick=()=>{agendaMonth=Number(b.dataset.month);agendaView="month";render()});document.querySelectorAll("[data-go]").forEach(b=>b.onclick=()=>go(b.dataset.go));document.querySelectorAll(".visual-open").forEach(b=>b.onclick=(ev)=>{ev.stopPropagation();$("#visualModalImg").src=b.dataset.visual;$("#visualModal").classList.add("show")});if($("#closeVisual"))$("#closeVisual").onclick=()=>$("#visualModal").classList.remove("show");if($("#visualModal"))$("#visualModal").onclick=e=>{if(e.target.id==="visualModal")e.currentTarget.classList.remove("show")};$("#back").onclick=()=>{let p=state.previous||"today";state.previous=state.page;state.page=p;save();render()};
if($("#monthPrev"))$("#monthPrev").onclick=()=>{agendaMonth=(agendaMonth+10)%11;render()};if($("#monthNext"))$("#monthNext").onclick=()=>{agendaMonth=(agendaMonth+1)%11;render()};
if($("#copyPronote"))$("#copyPronote").onclick=async()=>{let c=state.classes.find(x=>x.id===state.class),d=sessionData(c),plain=pronotePlain(c,d);try{await navigator.clipboard.writeText(plain);alert("Cahier de textes copié.");}catch(e){alert("Copie impossible : sélectionnez le contenu.");}};
if($("#savePronote"))$("#savePronote").onclick=()=>{let c=state.classes.find(x=>x.id===state.class),k=c.id+"-"+c.seq+"-"+c.session;state.pronote[k]=true;save();render()};
if($("#printTrace"))$("#printTrace").onclick=()=>window.print();
document.querySelectorAll("[data-st]").forEach(b=>b.onclick=()=>{let c=state.classes.find(x=>x.id===state.class),k=c.id+"-"+c.seq+"-"+c.session;state.status[k]=b.dataset.st;if(b.dataset.st==="done"&&c.session<maxS(c))c.session++;save();render()});
if($("#prevLesson"))$("#prevLesson").onclick=()=>{let c=state.classes.find(x=>x.id===state.class);if(c.session>1)c.session--;save();render()};if($("#nextLesson"))$("#nextLesson").onclick=()=>{let c=state.classes.find(x=>x.id===state.class);if(c.session<maxS(c))c.session++;save();render()};
if($("#export"))$("#export").onclick=()=>{let a=document.createElement("a"),blob=new Blob([JSON.stringify(state,null,2)],{type:"application/json"});a.href=URL.createObjectURL(blob);a.download="CAP-Espanol-2026-2027.json";a.click()};}

