    ...toCorrect.map(e=>({type:'eval',label:`${e.class?e.class+' • ':''}${e.key||'Évaluation'}`,detail:'Évaluation à corriger',page:'eval'})),
    ...attention.map(c=>({type:'attention',label:`${c.id} • ${term(c.level)} ${c.seq} • S${c.session}`,detail:state.status[currentKey(c)]==='review'?'À reprendre':'À poursuivre',page:'classes'})),
    ...upcomingEvals.filter(e=>{let d=parseISO(e.date);return d>=parseISO(ds)&&d<=next7}).map(e=>({type:'deadline',label:`${e.class?e.class+' • ':''}${e.key||'Évaluation'}`,detail:`Échéance ${e.date}`,page:'eval'}))
