function traceBlock(d,adapted=false){
  let x=adapted?d?.adapted:d;if(!x)return "";
  let g=x.grammar&&((x.grammar.point)||((x.grammar.examples||[]).length))?`<div class="trace-section"><b class="grammar-head">🔴 GRAMÁTICA / LENGUA</b>${grammarHTML(x.grammar)}</div>`:"";
  let hw=x.homework?`<div class="trace-section"><b class="tarea-head">🏠 TAREA</b><div class="trace-text">${x.homework}</div></div>`:"";
  return `<div class="trace-sheet ${adapted?"adapted":""}"><h4>${adapted?"📗 VERSION ADAPTÉE":"📝 MI HUELLA ESCRITA"}</h4><div class="trace-section"><b class="vocab-head">🟢 VOCABULARIO</b>${vocabHTML(x.vocab)}</div>${g}<div class="trace-section"><b class="culture-head">🔵 LO QUE RECUERDO</b>${(x.trace||[]).map(z=>`<div class="trace-text">${z}</div>`).join("")}</div>${hw}</div>`;
}

function resources(evalOnly=false){
  if(evalOnly)return evaluationsPage();
  head('RESSOURCES','Recherche et filtres • bibliothèque physique vérifiée');
  let base=DOCS.filter(d=>!isEval(d));
  let levels=['Tous','5e','4e','3e'],types=['Tous',...new Set(base.map(d=>d.category))];
  let arr=base;
  if(v15Res.level!=='Tous')arr=arr.filter(d=>d.level===v15Res.level);
  let seqs=['Tous',...Array.from(new Set(arr.filter(d=>d.seq!=null).map(d=>String(d.seq)))).sort((a,b)=>Number(a)-Number(b))];
  if(v15Res.seq!=='Tous')arr=arr.filter(d=>String(d.seq)===String(v15Res.seq));
  let sessions=['Tous',...Array.from(new Set(arr.filter(d=>d.session!=null).map(d=>String(d.session)))).sort((a,b)=>Number(a)-Number(b))];
  if(v15Res.session!=='Tous')arr=arr.filter(d=>String(d.session)===String(v15Res.session));
  if(v15Res.type!=='Tous')arr=arr.filter(d=>d.category===v15Res.type);
  if(v15Res.q.trim()){let q=v15Res.q.toLowerCase();arr=arr.filter(d=>(d.name+' '+d.category+' '+(d.seq??'')+' '+(d.session??'')).toLowerCase().includes(q))}
  return `<div class="resource-tools"><input id="resQ" placeholder="Rechercher une ressource…" value="${v15Res.q}"><select id="resLevel">${levels.map(x=>`<option ${x===v15Res.level?'selected':''}>${x}</option>`).join('')}</select><select id="resSeq">${seqs.map(x=>`<option ${x===v15Res.seq?'selected':''} value="${x}">${x==='Tous'?'Unidad / Secuencia':term(v15Res.level==='Tous'?'4e':v15Res.level)+' '+x}</option>`).join('')}</select><select id="resSession">${sessions.map(x=>`<option ${x===v15Res.session?'selected':''} value="${x}">${x==='Tous'?'Séance':'Séance '+x}</option>`).join('')}</select><select id="resType">${types.map(x=>`<option ${x===v15Res.type?'selected':''}>${x}</option>`).join('')}</select></div><div class="card"><p class="muted">${arr.length} ressource(s)</p><table><thead><tr><th>Niveau</th><th>Type</th><th>Document</th><th>Rattachement</th><th></th></tr></thead><tbody>${resourceRows(arr)}</tbody></table></div>`
}

