function specialSession(type,cls,n){state.previous=state.page;state.page='special';state.specialType=specialKey(type);state.specialClass=cls||'3C';state.specialSession=n||state.specialSession||1;save();render()}
function openSpecialSession(n){state.specialSession=Number(n);save();render();window.scrollTo({top:0,behavior:'smooth'})}
function specialPage(){let key=specialKey(state.specialType),m=SPECIAL_MODULES[key],cls=state.specialClass||'3C',n=Math.max(1,Math.min(18,Number(state.specialSession)||1)),s=m.sessions[n-1];head(m.label,`${cls} • CAP 3e • 1 h toutes les deux semaines`);return `<div class="special-module" style="--special:${m.accent}">
 <div class="special-visuals"><button class="special-visual visual-open" data-visual="${m.hero}"><img src="${m.hero}" alt="${m.label}"><span>Visuel d’identité • Agrandir</span></button><button class="special-visual visual-open" data-visual="${m.progress}"><img src="${m.progress}" alt="Progression ${m.label}"><span>Progression annuelle • Agrandir</span></button></div>
 <div class="card special-current"><div class="special-title"><span class="special-num">${n}</span><div><small>${s[0]} • ${cls}</small><h2>${s[1]}</h2><p>${m.tagline}</p></div></div><div class="special-detail-grid"><div><h3>OBJECTIF / FINALITÉ</h3><p>${s[2]}</p></div><div><h3>TRACE / PRODUCTION À GARDER</h3><p>À renseigner pendant ou à l’issue de la séance à partir de la production réelle de la classe.</p></div><div><h3>NOTES DE SUIVI</h3><textarea placeholder="Notes de séance…"></textarea></div><div><h3>PRONOTE</h3><p>${m.label} — Séance ${n} : ${s[1]}.<br>${s[2]}</p></div></div></div>
 <div class="card"><div class="special-prog-head"><div><h2>Progression annuelle</h2><p class="muted">18 ${key==='TSO'?'missions pour construire son parcours':'rendez-vous pour vivre, agir et progresser ensemble'}</p></div><span class="badge b3">2026-2027</span></div><div class="special-session-grid">${m.sessions.map((x,i)=>`<button class="special-session ${i+1===n?'active':''}" onclick="openSpecialSession(${i+1})"><b>${i+1}</b><span><small>${x[0]}</small><strong>${x[1]}</strong></span></button>`).join('')}</div></div>
 </div>`}


function capClockText(){
  const now=new Date();
  const time=now.toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'});
  let date=now.toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long',year:'numeric'});
  date=date.charAt(0).toUpperCase()+date.slice(1);
  const parts=time.split(':');
  return `<span class="clock-time">${parts[0]}<span class="clock-colon">:</span>${parts[1]}</span><span class="clock-date"> · ${date}</span>`;
}
function updateCapClock(){
  const html=capClockText();
  const el=document.getElementById('capClock');
  if(el)el.innerHTML=html;
  const homeEl=document.getElementById('capClockHome');
  if(homeEl)homeEl.innerHTML=html;
}

